{ config, lib, pkgs, meta, ... }:
{
  imports = [
    ../common
  ];

  boot.initrd.availableKernelModules = [
    "ahci"
    "sd_mod"
    "sr_mod"
    "virtio_pci"
    "virtio_scsi"
    "virtio_blk"
  ];

  system.stateVersion = "25.05";

  networking.firewall.allowedTCPPorts = [ 22 10250 ];
  networking.firewall.allowedUDPPorts = [ 8472 ];

  services.openssh = {
    enable = true;
    settings = {
      PermitRootLogin = "prohibit-password";
      PasswordAuthentication = false;
    };
  };

  services.vigilAutoReconciler.enable = true;
}

{ ... }:
{
  imports = [
    ./disko.nix
    ./boot.nix
    ./locale.nix
    ./networking.nix
    ./nix-settings.nix
    ./packages.nix
    ./users.nix
  ];
}

{ diskDevice, ... }:
let
  # udevadm settle can return before udev recreates the partition links after the last table re-read
  waitForPartitionLink = ''udevadm wait --settle --timeout 60 "$device"'';
in
{
  disko.devices.disk.main = {
    type = "disk";
    device = diskDevice;
    content = {
      type = "gpt";
      partitions = {
        bios = {
          size = "1M";
          type = "EF02";
        };
        ESP = {
          size = "512M";
          type = "EF00";
          content = {
            type = "filesystem";
            format = "vfat";
            mountpoint = "/boot";
            preCreateHook = waitForPartitionLink;
          };
        };
        root = {
          size = "100%";
          content = {
            type = "filesystem";
            format = "ext4";
            mountpoint = "/";
            preCreateHook = waitForPartitionLink;
          };
        };
      };
    };
  };
}

{ diskDevice, pkgs, ... }:
{
  boot.loader.grub = {
    enable = true;
    device = if pkgs.stdenv.hostPlatform.isx86 then diskDevice else "nodev";
    efiSupport = true;
    efiInstallAsRemovable = true;
  };
}

{ ... }:
{
  time.timeZone = "Europe/Berlin";
  i18n.defaultLocale = "en_US.UTF-8";
  console = {
    font = "Lat2-Terminus16";
    keyMap = "de";
  };
}

{ ... }:
{
  networking.useDHCP = true;

  services.resolved.enable = true;

  networking.firewall = {
    enable = true;
    allowedTCPPorts = [ 22 ];
  };
}

{ ... }:
{
  documentation.enable = false;

  nix.settings = {
    experimental-features = [ "nix-command" "flakes" ];
    trusted-users = [ "root" "@wheel" ];
  };
}

{ pkgs, ... }:
{
  environment.systemPackages = with pkgs; [
    neovim
    k3s
    cifs-utils
    nfs-utils
    git
    age
    htop
    tmux
    tree
  ];
}

{ meta, ... }:
{
  users.users.${meta.hostname} = {
    isNormalUser = true;
    extraGroups = [ "wheel" ];
  };

  security.sudo.wheelNeedsPassword = false;

  services.openssh.enable = true;
}

</vigil-data-f1a3d2415a7d>
